import{v as b,x,C as y,o as n,c as d,E as P,a2 as u,j as r,t as g,b as S,w as T,k as A,g as h,T as v,F as C,B as k,n as w,p}from"./chunks/framework.BsHbenZx.js";const F={class:"promo-image-area"},D={class:"slide-container"},L={key:0,class:"placeholder-container"},G={class:"placeholder-content"},H={class:"placeholder-icon"},I={class:"placeholder-text"},R=["src","alt"],M={class:"slide-label"},V={class:"slide-dots"},q=["onClick","aria-label"],z=JSON.parse('{"title":"塗りに質感を与える","description":"DaVinci Resolveで水滴・ラメ・ステンドグラス・金属光沢・網点など、塗りに重ねるだけで文字に質感を与える13種類のマテリアルの使い方","frontmatter":{"title":"塗りに質感を与える","description":"DaVinci Resolveで水滴・ラメ・ステンドグラス・金属光沢・網点など、塗りに重ねるだけで文字に質感を与える13種類のマテリアルの使い方","pageClass":"feature-guide","aside":false,"head":[["link",{"rel":"alternate","hreflang":"ja","href":"https://mug-typography.muglab3.com/features/feature-texture.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://mug-typography.muglab3.com/en/features/feature-texture.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://mug-typography.muglab3.com/features/feature-texture.html"}],["link",{"rel":"canonical","href":"https://mug-typography.muglab3.com/features/feature-texture.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography 公式マニュアル"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"塗りに質感を与える | Mug Typography 公式マニュアル"}],["meta",{"property":"og:description","content":"DaVinci Resolveで水滴・ラメ・ステンドグラス・金属光沢・網点など、塗りに重ねるだけで文字に質感を与える13種類のマテリアルの使い方"}],["meta",{"property":"og:url","content":"https://mug-typography.muglab3.com/features/feature-texture.html"}],["meta",{"property":"og:image","content":"https://mug-typography.muglab3.com/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography 公式マニュアル"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"塗りに質感を与える | Mug Typography 公式マニュアル"}],["meta",{"name":"twitter:description","content":"DaVinci Resolveで水滴・ラメ・ステンドグラス・金属光沢・網点など、塗りに重ねるだけで文字に質感を与える13種類のマテリアルの使い方"}],["meta",{"name":"twitter:image","content":"https://mug-typography.muglab3.com/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography 公式マニュアル"}]]},"headers":[],"relativePath":"features/feature-texture.md","filePath":"features/feature-texture.md"}'),E={name:"features/feature-texture.md"},j=Object.assign(E,{setup(B){const e=[{name:"Water Droplet（水滴）",img:"/image/texture_water_droplet.webp",icon:"💧"},{name:"Air Cushion（エアクッション）",img:"/image/texture_air_cushion.webp",icon:"🫧"},{name:"Glitter（ラメ）",img:"/image/texture_glitter.webp",icon:"✨"},{name:"Iridescent（虹色）",img:"/image/texture_iridescent.webp",icon:"🌈"},{name:"Faceted（多面体）",img:"/image/texture_faceted.webp",icon:"💎"},{name:"Stained Glass（ステンドグラス）",img:"/image/texture_stained_glass.webp",icon:"🪟"},{name:"Metallic（金属光沢）",img:"/image/texture_metallic.webp",icon:"🥇"},{name:"Metallic 2（金属光沢・強）",img:"/image/texture_metallic_2.webp",icon:"🪙"},{name:"Stripe（縞）",img:"/image/texture_stripe.webp",icon:"🦓"},{name:"Colored Pencil（色鉛筆）",img:"/image/texture_colored_pencil.webp",icon:"✏️"},{name:"Halftone（網点）",img:"/image/texture_halftone.webp",icon:"🔘"},{name:"Halftone Diamond（ひし形の網点）",img:"/image/texture_halftone_diamond.webp",icon:"🔶"},{name:"Prism Foil（プリズム箔）",img:"/image/texture_prism_foil.webp",icon:"🪩"}],t=p(0),c=p(e.map(()=>!1));let i=null;const m=()=>{i=setInterval(()=>{t.value=(t.value+1)%e.length},4e3)},_=a=>{t.value=a,clearInterval(i),m()};return b(()=>{e.forEach((a,o)=>{const s=new Image;s.onload=()=>{c.value[o]=!0},s.src=h(a.img)}),m()}),x(()=>clearInterval(i)),(a,o)=>{const s=y("FeatureHero");return n(),d("div",null,[P(s,{eyebrow:"FILL MATERIAL",title:"文字に質感をまとわせる",description:"水滴、ラメ、虹色、ステンドグラス。組み込みのマテリアルを選ぶだけで、平坦な塗りが素材感のある表面に変わります。下地の色やグラデーションはそのまま活かされます。",image:"/image/texture_hero.webp","image-alt":"ステンドグラスのマテリアルを適用したテキスト","detail-link":"/reference/reference-global-settings#テクスチャ-texture","point-one":"13種類のマテリアル","point-two":"最大5つのつまみで調整","point-three":"下地の色を活かす","is-new":!0}),o[1]||(o[1]=u('<h2 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h2><ol><li><strong>Page</strong> を <code>Global Settings</code> にします。</li><li><strong>Color Settings</strong> の <strong>Texture</strong> グループを開きます。</li><li><strong>Texture</strong> でマテリアルを選びます。</li><li><strong>P1</strong>〜<strong>P5</strong>（選んだマテリアルに応じて名前が変わります。P5は、使うマテリアルを選んだときだけ表示されます）で質感を調整します。</li><li><strong>Texture Color</strong> で色を調整します。</li></ol><h2 id="マテリアルごとの違い" tabindex="-1">マテリアルごとの違い <a class="header-anchor" href="#マテリアルごとの違い" aria-label="Permalink to &quot;マテリアルごとの違い&quot;">​</a></h2>',3)),r("div",F,[r("div",D,[c.value[t.value]?(n(),S(v,{key:1,name:"fade",mode:"out-in"},{default:T(()=>[(n(),d("img",{key:t.value,class:"promo-gif",src:A(h)(e[t.value].img),alt:e[t.value].name},null,8,R))]),_:1})):(n(),d("div",L,[r("div",G,[r("span",H,g(e[t.value].icon),1),r("span",I,g(e[t.value].name),1),o[0]||(o[0]=r("span",{class:"placeholder-subtext"},"Coming soon",-1))])]))]),r("span",M,g(e[t.value].name),1),r("div",V,[(n(),d(C,null,k(e,(f,l)=>r("button",{key:l,onClick:N=>_(l),class:w([{active:t.value===l},"slide-dot"]),"aria-label":f.name},null,10,q)),64))])]),o[2]||(o[2]=u('<table tabindex="0"><thead><tr><th>マテリアル</th><th>特徴</th></tr></thead><tbody><tr><td><strong>Water Droplet</strong></td><td>文字が水を含んでぷっくりと盛り上がり、表面に光沢が乗ります。窓ガラスを流れる水滴や、濡れたゼリーのような見た目です。</td></tr><tr><td><strong>Air Cushion</strong></td><td>縁が圧着され、内側が膨らんだフィルム。空気で膨らませた包装材のような質感です。</td></tr><tr><td><strong>Glitter</strong></td><td>細かな金属片を密に重ね、光の方向に合った粒がきらめきます。ストロークの上にも乗ります。</td></tr><tr><td><strong>Iridescent</strong></td><td>薄膜干渉による虹色。見る角度で色が変わる、シャボン玉や玉虫色の質感です。<strong>Film Variation</strong> を上げると、膜厚のムラで油膜のように色が流れます。</td></tr><tr><td><strong>Faceted</strong></td><td>石に彫った文字のように、輪郭から内側へ傾いた平らな面で文字を切り出します。面はまっすぐな稜線で合わさり、くっきりと光と影に分かれます。</td></tr><tr><td><strong>Stained Glass</strong></td><td>塗りを色ガラスの断片に分割し、鉛線で縁取ります。</td></tr><tr><td><strong>Metallic</strong></td><td>研磨の筋が走るヘアライン仕上げの金属です。塗り色がそのまま金属の色になり、黄土色なら金、明るい灰色なら銀、赤茶色なら銅に見えます。<strong>Hairline Angle</strong> で筋の向きを変えられます。</td></tr><tr><td><strong>Metallic 2</strong></td><td>空と地平線が映り込むクロームメッキです。くっきりした明暗の切り替わりで強く光ります。<strong>Exposure</strong> で明るさそのものを調整できます。</td></tr><tr><td><strong>Stripe</strong></td><td>塗りの上に、指定した色の平行な縞を重ねます。縞の本数・太さ・角度・濃さを調整できます。</td></tr><tr><td><strong>Colored Pencil</strong></td><td>ベタ塗りの塗り色に、白い細い線（塗り残し）が不規則に散ります。光の当たる側の縁は白く塗り残され、色鉛筆で白い紙に塗ったような見た目になります。下地の塗り色が鉛筆の色、<strong>Texture Color</strong> が紙の色です。</td></tr><tr><td><strong>Halftone</strong></td><td>塗りの上に、指定した色の丸い網点を格子状に並べます。<strong>Fade</strong> を上げると点が小さくなっていき、<strong>Fade Angle</strong> で小さくなる向きを決められます（<code>0</code> で下へ向かって濃くなります）。</td></tr><tr><td><strong>Halftone Diamond</strong></td><td>Halftone と同じ網点を、ひし形の点で並べます。点の大きさは丸と同じ面積で揃うので、切り替えても濃さは変わりません。</td></tr><tr><td><strong>Prism Foil</strong></td><td>塗りを銀色のプリズム箔に置き換えます。正方形のタイルの中心から光の筋と虹色が放射状に広がる、ホログラムのシールのような見た目です。<strong>Light Angle</strong> を動かすと、光を受けるタイルと筋が移り変わります。</td></tr></tbody></table><h2 id="コントロールの対応表" tabindex="-1">コントロールの対応表 <a class="header-anchor" href="#コントロールの対応表" aria-label="Permalink to &quot;コントロールの対応表&quot;">​</a></h2><p>5つのコントロール（P1〜P5）はマテリアル共通の汎用スロットで、選んだマテリアルに応じて名前が変わります（P5は使用するマテリアルを選んだときだけ表示されます）。</p><table tabindex="0"><thead><tr><th>Texture</th><th>P1</th><th>P2</th><th>P3</th><th>P4</th><th>P5</th></tr></thead><tbody><tr><td><strong>Water Droplet</strong></td><td>Thickness</td><td>Roundness</td><td>Gloss</td><td>Light Angle</td><td>-</td></tr><tr><td><strong>Air Cushion</strong></td><td>Inflation</td><td>Seal Width</td><td>Wrinkles</td><td>Light Angle</td><td>-</td></tr><tr><td><strong>Glitter</strong></td><td>Flake Size</td><td>Highlight Ratio</td><td>Flake Amount</td><td>Light Angle</td><td>-</td></tr><tr><td><strong>Iridescent</strong></td><td>Film Thickness</td><td>Hue Range</td><td>Strength</td><td>Light Angle</td><td>Film Variation</td></tr><tr><td><strong>Faceted</strong></td><td>Facets</td><td>Bevel Depth</td><td>Polish</td><td>Light Angle</td><td>-</td></tr><tr><td><strong>Stained Glass</strong></td><td>Piece Size</td><td>Lead Width</td><td>Hue Range</td><td>Glow</td><td>-</td></tr><tr><td><strong>Metallic</strong></td><td>Polish</td><td>Relief</td><td>Reflection Contrast</td><td>Light Angle</td><td>Hairline Angle</td></tr><tr><td><strong>Metallic 2</strong></td><td>Polish</td><td>Relief</td><td>Exposure</td><td>Light Angle</td><td>-</td></tr><tr><td><strong>Stripe</strong></td><td>Stripe Density</td><td>Stripe Width</td><td>Strength</td><td>Stripe Angle</td><td>-</td></tr><tr><td><strong>Colored Pencil</strong></td><td>Scratch Density</td><td>Scratch Length</td><td>Light Amount</td><td>Stroke Angle</td><td>Light Angle</td></tr><tr><td><strong>Halftone</strong></td><td>Dot Density</td><td>Dot Size</td><td>Fade</td><td>Grid Angle</td><td>Fade Angle</td></tr><tr><td><strong>Halftone Diamond</strong></td><td>Dot Density</td><td>Dot Size</td><td>Fade</td><td>Grid Angle</td><td>Fade Angle</td></tr><tr><td><strong>Prism Foil</strong></td><td>Tile Size</td><td>Hue Range</td><td>Strength</td><td>Light Angle</td><td>Grid Angle</td></tr></tbody></table><p>角度（<code>0</code>〜<code>360</code>）のコントロールは <strong>Light Angle</strong>・<strong>Stripe Angle</strong>・<strong>Grid Angle</strong>・<strong>Fade Angle</strong>・<strong>Stroke Angle</strong> で、それ以外はすべて <code>0</code>〜<code>1</code> です。Stained Glass の <strong>Glow</strong> は同じ第4スロットですが角度ではなく、中央の <code>0.5</code> が素のガラス、上げると発光、下げると暗くなります。</p><h2 id="下地の色を活かす" tabindex="-1">下地の色を活かす <a class="header-anchor" href="#下地の色を活かす" aria-label="Permalink to &quot;下地の色を活かす&quot;">​</a></h2><p>マテリアルは塗りを置き換えるのではなく、その<strong>上に重ねて</strong>描かれます（<strong>Prism Foil</strong> だけは例外で、下の段落を参照してください）。Font Color やグラデーション、文字ごとの個別色がそのまま下地として残るため、色の選び方が仕上がりに直結します。</p><p>ただし色の決まり方はマテリアルによって違います。<strong>Stained Glass</strong> は下地の<strong>色相を起点</strong>に各ガラス片の色を決めるため、下地の色がそのまま作品の色調になります。一方 <strong>Glitter</strong> の金属片は <strong>Texture Color</strong> を基本色とし、下地ではなくそちらで色を決めます。</p><p><strong>Stripe</strong>・<strong>Halftone</strong>・<strong>Halftone Diamond</strong> は、縞や点を <strong>Texture Color</strong> で描きます。<strong>Colored Pencil</strong> は逆に、下地の塗り色が鉛筆の色になり、<strong>Texture Color</strong> は塗り残しの白い線の色（紙の色）です。</p><p><strong>Prism Foil</strong> は塗りを箔で置き換えるため、下地の色は <strong>Strength</strong> を下げたときにだけ透けて見えます。箔の色は <strong>Texture Color</strong> で決まり、既定の白で銀、黄色寄りにすると金の箔になります。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Stained Glass をグラデーションと組み合わせると、位置によってガラス片の色が変わります。単色では作りにくい表情が出せます。</p></div><h2 id="組み合わせのレシピ" tabindex="-1">組み合わせのレシピ <a class="header-anchor" href="#組み合わせのレシピ" aria-label="Permalink to &quot;組み合わせのレシピ&quot;">​</a></h2><p><strong>金色に輝くラメ</strong></p><ol><li><strong>Texture</strong> を <code>Glitter</code> にします。</li><li><strong>Texture Color</strong> を金色にします。金属片の基本色になります。</li><li><strong>Flake Amount</strong>（P3）で粒の密度を決めます。</li><li><strong>Highlight Ratio</strong>（P2）を上げると、強く光る粒が増えます。</li><li><strong>Light Angle</strong>（P4）にキーフレームを打つと、光る粒が入れ替わってきらめきが動きます。</li></ol><p><strong>単色ガラスから多色ガラスへ</strong></p><ol><li><strong>Texture</strong> を <code>Stained Glass</code> にします。</li><li><strong>Hue Range</strong>（P3）を <code>0</code> にすると、塗りの色相を保った単色のガラスになります。</li><li><strong>Hue Range</strong> に <code>0</code> から <code>1</code> へのキーフレームを打つと、色が広がっていくアニメーションになります。</li></ol><h2 id="スクリプトからの制御" tabindex="-1">スクリプトからの制御 <a class="header-anchor" href="#スクリプトからの制御" aria-label="Permalink to &quot;スクリプトからの制御&quot;">​</a></h2><p><code>ctx.global.texture</code> で全体のマテリアルとコントロールを設定できるほか、<code>ctx.chars[i].texture</code> / <code>ctx.parts[i].texture</code> に <code>use = true</code> を指定すると、文字やパーツ単位で別のマテリアルに差し替えられます（文字・パーツ単位での別マテリアル指定はLuaスクリプトからのみ行えます）。詳しくは「<a href="/features/feature-scripting.html">Luaスクリプトで動かす</a>」を参照してください。</p><h2 id="思ったとおりにならないとき" tabindex="-1">思ったとおりにならないとき <a class="header-anchor" href="#思ったとおりにならないとき" aria-label="Permalink to &quot;思ったとおりにならないとき&quot;">​</a></h2><ul><li><strong>マテリアルが何も出ない</strong> - <strong>Transparent Fill</strong> がONになっていないか確認してください。塗り自体が描かれなくなるため、その上に重なるマテリアルも消えます（個別カラーを指定した文字・パーツだけは残ります）。</li><li><strong>Texture Color を変えても色が変わらない</strong> - <strong>Iridescent</strong> を選んでいませんか。このマテリアルは薄膜干渉そのものから色が決まるため、Texture Color を無視します。</li><li><strong>Colored Pencil の線が出ない</strong> - <strong>Scratch Density</strong>（P1）が <code>0</code> になっていないか確認してください。<code>0</code> では白い線が出ません。光の当たる縁の塗り残しは <strong>Light Amount</strong>（P3）で決まるため、<code>0</code> にすると、それも出ません。</li><li><strong>Prism Foil に下地の色が出ない</strong> - 箔が塗りを置き換えるためです。下地の色を混ぜたいときは <strong>Strength</strong>（P3）を下げてください。</li><li><strong>MT Sim と実際の描画が違う</strong> - MT Sim（VSCode拡張）のテクスチャ表示は簡易的なプレビューです。Colored Pencil では、光に面した縁の塗り残しを表示しません。Prism Foil は、タイルの中の光の筋を少数の扇形に分けて塗るため、筋の境目が角張って見えます。Iridescent の Film Variation は表示に反映されません。マテリアルの選択とコントロールの効きは確認できますが、最終的な見た目はプラグイン本体で確認してください。</li></ul>',20))])}}});export{z as __pageData,j as default};
